class AuthDialog {
    private final EventBus bus = new EventBus();

    AuthDialog(Checkbox login, Textbox email) {
        bus.register(new Object() {
            @Subscribe public void onCheck(CheckEvent e) {
                email.setEnabled(!e.checked());
            }
        });
    }
    void check(boolean checked) { bus.post(new CheckEvent(checked)); }
}
